// @wicklib/api 1
import { defineScript, ta } from "@wicklib/script";

export default defineScript({
  inputs: {},
  plots: [
    { id: "sma", title: "SMA", type: "line" },
    { id: "ema", title: "EMA", type: "line" },
    { id: "rsi", title: "RSI", type: "line" },
    { id: "atr", title: "ATR", type: "line" },
    { id: "stdev", title: "Stdev", type: "line" },
    { id: "change", title: "Change", type: "line" },
    { id: "roc", title: "ROC", type: "line" },
    { id: "cum", title: "Cum", type: "line" },
  ],
  onBar(ctx) {
    ctx.plot("sma", ta.sma(ctx, "close", 3));
    ctx.plot("ema", ta.ema(ctx, "close", 3));
    ctx.plot("rsi", ta.rsi(ctx, "close", 2));
    ctx.plot("atr", ta.atr(ctx, 2));
    ctx.plot("stdev", ta.stdev(ctx, "close", 3));
    ctx.plot("change", ta.change(ctx, "close"));
    ctx.plot("roc", ta.roc(ctx, "close"));
    ctx.plot("cum", ta.cum(ctx, "close"));
  },
});
